#!/bin/bash
set -euo pipefail
DEST="${1:-$HOME/tartarus-linux}"
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
base64 -d << 'B64' | tar xzf - -C "$TMP"

B64
mkdir -p "$DEST/src"
cp -f "$TMP"/src/*.rs "$DEST/src/"
cp -f "$TMP/Cargo.toml" "$DEST/Cargo.toml"
cp -f "$TMP/config.example.toml" "$DEST/config.example.toml" 2>/dev/null || true
cd "$DEST"
cargo build --release
echo "OK"
echo "  pkill -f tartarus-linux || true"
echo "  $DEST/target/release/tartarus-linux"
